_current_lang = "en"


def current_lang() -> str:
    return _current_lang


def set_lang(code: str) -> None:
    global _current_lang
    if code in LANGUAGES:
        _current_lang = code


def system_lang() -> str:
    try:
        from PySide6.QtCore import QLocale
        langs = QLocale.system().uiLanguages()
        code = langs[0].replace("_", "-").split("-")[0].lower() if langs else ""
    except Exception:
        return "en"
    return code if code in LANGUAGES else "en"


def pick_lang(settings: dict) -> str:
    code = settings.get("language")
    return code if code in LANGUAGES else system_lang()


def _plural_category(lang: str, n: int) -> str:
    """Plural category for T_count(): 'one' / 'few' / 'many'. Polish has three forms (1
    kopia, 2-4 kopie, 5+ kopii, except 12-14, which go to 'many' despite ending in
    2-4). The other supported languages (en/fr/de/es) distinguish only singular from
    plural, so 'few' is never returned for them: n==1 is 'one', the rest is 'many'.
    """
    if lang == "pl":
        if n == 1:
            return "one"
        n_mod10, n_mod100 = n % 10, n % 100
        if 2 <= n_mod10 <= 4 and not (12 <= n_mod100 <= 14):
            return "few"
        return "many"
    return "one" if n == 1 else "many"


def T_count(key: str, count: int, **kwargs) -> str:
    suffixed = f"{key}_{_plural_category(_current_lang, count)}"
    if suffixed not in _STRINGS:
        suffixed = key
    return T(suffixed, count=count, **kwargs)


def errors_summary(errors: list) -> str:
    generic = T("leftover_errors_msg")
    if len(errors) == 1 and errors[0] == generic:
        return generic
    return T_count("leftover_errors_count_msg", len(errors))


def T(key: str, **kwargs) -> str:
    entry = _STRINGS.get(key)
    if entry is None:
        return key
    text = entry.get(_current_lang) or entry.get("en") or key
    if kwargs:
        try:
            return text.format(**kwargs)
        except Exception:
            return text
    return text
